impl Solution {
    pub fn detect_capital_use(word: String) -> bool {
        let all_upper = word.chars().all(|c| c.is_uppercase());
        let all_lower = word.chars().all(|c| c.is_lowercase());
        let first_upper_rest_lower = word.chars().next().map_or(false, |c| c.is_uppercase()) &&
            word.chars().skip(1).all(|c| c.is_lowercase());

        all_upper || all_lower || first_upper_rest_lower
    }
}

